export default {
  name: "ToggleDark",
  data() {
    return {
      themeList: ["auto", "light", "dark"],
      theme: this.$store.state.base.theme
    };
  },
  methods: {
    handleToggleClick() {
      const currentIndex = this.themeList.indexOf(this.theme);
      const nextIndex = (currentIndex + 1) % this.themeList.length;
      this.theme = this.themeList[nextIndex];
      this.$store.commit("base/setTheme", this.theme);
    }
  }
};